class Solution:
    def isPalindrome(self, x: int) -> bool:
        if x < 0:
            return False

        reversed_x = 0
        tmp = x
        while tmp > 0:
            last_digit = tmp % 10          # Get the last digit
            reversed_x = (reversed_x * 10) + last_digit  # Shift and add
            tmp //= 10                     # Remove the last digit

        return reversed_x == x
